final class InsufficientStockException extends RuntimeException {
    InsufficientStockException(String message) {
        super(message);
    }
}

final class Inventory {
    private final int stock;

    Inventory(int stock) {
        if (stock < 0) throw new IllegalArgumentException("재고는 음수일 수 없습니다.");
        this.stock = stock;
    }

    int remove(int requested) {
        if (requested < 0) throw new IllegalArgumentException("요청 수량은 음수일 수 없습니다.");
        if (requested > stock) throw new InsufficientStockException("재고가 부족합니다.");
        return stock - requested;
    }
}

